package main

import (
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
)

func inspect(code string) {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "main.go", code, 0)
	conf := types.Config{Importer: importer.Default()}
	info := &types.Info{Types: make(map[ast.Expr]types.TypeAndValue), Uses: make(map[*ast.Ident]types.Object), Selections: make(map[*ast.SelectorExpr]*types.Selection)}
	pkg, _ := conf.Check("example.com/m", fset, []*ast.File{f}, info)
	fmt.Println("pkg:", pkg)
	for sel, selection := range info.Selections {
		fmt.Printf("sel %s obj=%v type=%v recv=%v pkg=%v\n", sel.Sel.Name, selection.Obj(), selection.Type(), selection.Obj().(*types.Func).Type(), selection.Obj().(*types.Func).Pkg())
		// recv type?
		sig := selection.Obj().(*types.Func).Type().(*types.Signature)
		if sig.Recv() != nil {
			fmt.Printf("  recv type string: %s\n", sig.Recv().Type().String())
		}
		// fullName? try String?
		fmt.Printf("  obj string: %s\n", selection.Obj().String())
	}
	for ident, obj := range info.Uses {
		if _, ok := obj.(*types.Func); ok {
			fmt.Printf("uses func %s pkg=%v\n", ident.Name, obj.(*types.Func).Pkg())
		}
	}
}

func main() {
	fmt.Println("=== hash.Hash ===")
	inspect(`package main
import "hash"
func foo(h hash.Hash) {
	h.Write([]byte("hi"))
}
`)
	fmt.Println("=== io.Writer ===")
	inspect(`package main
import "io"
func foo(w io.Writer) {
	w.Write([]byte("hi"))
}
`)
}
EOF
go run /tmp/inspect.go 2>&1 | head -n 50"}

