func parseExcludeLine(line string) (base, suffix string, hasSuffix bool) {
	if strings.HasSuffix(line, ")") {
		idx := strings.LastIndex(line, "(")
		if idx >= 0 {
			base = line[:idx]
			suffix = line[idx+1 : len(line)-1]
			hasSuffix = true
			return
		}
	}
	return line, "", false
}

