	re  *regexp.Regexp
	raw string
}

func (f *ignoreFlag) String() string { return "" }
func (f *ignoreFlag) Set(s string) error {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	for _, p := range parts {
		var pkg, reStr string
		if idx := strings.Index(p, ":"); idx >= 0 {
			pkg = p[:idx]
			reStr = p[idx+1:]
		} else {
			pkg = ""
			reStr = p
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return err
		}
		*f = append(*f, ignoreEntry{pkg: pkg, re: re, raw: p})
	}
	return nil
}

type tagsFlag []string

func (f *tagsFlag) String() string { return "" }
func (f *tagsFlag) Set(s string) error {
	// split by comma or space (any whitespace and comma)
	// Use FieldsFunc with comma and space
	if s == "" {
		return nil
	}
	// Replace commas with spaces then Fields (splits on any whitespace)
	tmp := strings.ReplaceAll(s, ",", " ")
	fields := strings.Fields(tmp)
	*f = append(*f, fields...)
	return nil
}

