// listPackage mirrors go list JSON
type listPackage struct {
	Dir              string
	ImportPath       string
	ForTest          string
	GoFiles          []string
	CompiledGoFiles  []string
	TestGoFiles      []string
	XTestGoFiles     []string
	IgnoredGoFiles   []string
	Error            *listError
	Incomplete       bool
	Deps             []string
	Match            []string
	Export           string
}

type listError struct {
	ImportStack []string
	Pos         string
	Err         string
}

func loadPackages(patterns, tags []string, mod string) ([]*listPackage, error) {
	args := []string{"list", "-e", "-json", "-compiled", "-test", "-export"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, " "))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	// Use current dir, env?
	var stdout, stderr strings.Builder
	// Need to capture stdout as stream of JSON objects, stderr as string
	// Use Combined? No, separate.
	cmd.Stdout = &stdout
	var stderrBuf strings.Builder
	cmd.Stderr = &stderrBuf
	err := cmd.Run()
	if err != nil {
		// go list failed (non-zero exit)
		// err is *exec.ExitError with ExitCode? Format as "err: exit status X: stderr: <stderr>"
		// Need exit code
		exitCode := 1
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		}
		return nil, fmt.Errorf("err: exit status %d: stderr: %s", exitCode, stderrBuf.String())
	}
	// Parse JSON stream
	dec := json.NewDecoder(strings.NewReader(stdout.String()))
	var pkgs []*listPackage
	for {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			break
		}
		// Need to copy? Append pointer
		cp := p
		pkgs = append(pkgs, &cp)
	}
	// If no packages? e.g., empty? Return empty (no error). Good.
	return pkgs, nil
}
