func parseExcludeLine(line string) (string, string, bool) {
	if strings.HasSuffix(line, ")") {
		idx := strings.LastIndex(line, "(")
		if idx >= 0 {
			return line[:idx], line[idx+1 : len(line)-1], true
		}
	}
	return line, "", false
}

