type listPackage struct {
	Dir             string     `json:"Dir"`
	ImportPath      string     `json:"ImportPath"`
	ForTest         string     `json:"ForTest"`
	GoFiles         []string   `json:"GoFiles"`
	CompiledGoFiles []string   `json:"CompiledGoFiles"`
	TestGoFiles     []string   `json:"TestGoFiles"`
	XTestGoFiles    []string   `json:"XTestGoFiles"`
	Error           *listError `json:"Error"`
	Deps            []string   `json:"Deps"`
	Match           []string   `json:"Match"`
}

type listError struct {
	ImportStack []string `json:"ImportStack"`
	Pos         string   `json:"Pos"`
	Err         string   `json:"Err"`
}

func loadPackages(patterns []string, tags []string, mod string) ([]*listPackage, error) {
	args := []string{"list", "-e", "-json", "-compiled", "-test", "-export"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, " "))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var stdout strings.Builder
	var stderrBuf strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderrBuf
	err := cmd.Run()
	if err != nil {
		exitCode := 1
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		}
		return nil, fmt.Errorf("err: exit status %d: stderr: %s", exitCode, stderrBuf.String())
	}
	dec := json.NewDecoder(strings.NewReader(stdout.String()))
	var pkgs []*listPackage
	for {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			break
		}
		cp := p
		pkgs = append(pkgs, &cp)
	}
	return pkgs, nil
}

type importerFunc func(path string) (*types.Package, error)

func (f importerFunc) Import(path string) (*types.Package, error) { return f(path) }

type pkgResult struct {
	pkg       *listPackage
	files     []*ast.File
	info      *types.Info
	typePkg   *types.Package
	parseErrs []string
	typeErrs  []string
	fileSrc   map[string][]byte
	fnames    []string // absolute filenames in order
}

type report struct {
	filename string // as to print (relative or absolute)
	absFile  string
	line     int
	col      int
	funcName string // for verbose ("" if none)
	stmt     string
