func run() int {
	var userExcludes []exclEntry
	if *flagExclude != "" {
		f, err := os.Open(*flagExclude)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
			return 2
		}
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			line := sc.Text()
			if line == "" {
				continue
			}
			if strings.HasPrefix(line, "//") {
				continue
			}
			b, s, h := parseExcludeLine(line)
			userExcludes = append(userExcludes, exclEntry{b, s, h})
		}
		f.Close()
	}
	var allExcludes []exclEntry
	if *flagExcludeOnly {
		allExcludes = userExcludes
	} else {
		for _, b := range builtinExcludes() {
			bb, ss, hh := parseExcludeLine(b)
			allExcludes = append(allExcludes, exclEntry{bb, ss, hh})
		}
		allExcludes = append(allExcludes, userExcludes...)
	}
	ignorePkgsSet := map[string]bool{}
	if *flagIgnorePkgStr != "" {
		for _, p := range strings.Split(*flagIgnorePkgStr, ",") {
