		}
	}
	patterns := flag.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}
	pkgs, err := loadPackages(patterns, []string(*flagTags), *flagMod)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		return 2
	}
	// verbose checking order
	toPrint := pkgs
	if len(pkgs) > 0 {
		allSame := true
		d0 := pkgs[0].Dir
		for _, p := range pkgs[1:] {
			if p.Dir != d0 {
				allSame = false
				break
			}
		}
		if allSame {
			tmp := make([]*listPackage, len(pkgs))
			copy(tmp, pkgs)
			sort.Slice(tmp, func(i, j int) bool { return tmp[i].ImportPath < tmp[j].ImportPath })
			toPrint = tmp
		}
	}
	if *flagVerbose {
		for _, p := range toPrint {
			path := p.ImportPath
