		}
		if relErr != "" || len(absErrs) > 0 {
			// build message: errors while loading package <ImportPath>: [<-: relErr> <absErrs...>]
			// relErr already is like "# pkg\n./file:..." (with relative). Format first as "-: <relErr>"? Actually need "[-: <relErr> <abs1> <abs2>...]"?
