			}
			src, ok := res.fileSrc[fn]
			if !ok {
				continue
			}
			fileMap[fn] = &fileInfo{info: res.info, src: src, pkg: p}
		}
	}
	// Now check each file
	for abs, fi := range fileMap {
		// filter _test.go?
		if *flagIgnoreTests && strings.HasSuffix(abs, "_test.go") {
			continue
		}
		// filter generated?
		if *flagIgnoreGenerated && isGenerated(fi.src) {
			continue
		}
		// find ast.File for this abs? Need to find in results? We have files per package, but fileMap doesn't store ast.File. Let's store ast.File as well.
