			abs := pos.Filename
			// fset filename is as given to ParseFile (absolute). Good.
			if checkedAbs[abs] {
				continue
			}
			checkedAbs[abs] = true
			// filter?
			src := res.fileSrc[abs]
			if src == nil {
				// try to find src by abs? res.fileSrc keyed by abs as constructed (Dir+File). Should match. Good.
				continue
