	_ = isErrorResult
	_ = isErrorType
	// Walk to find calls and asserts
	// For asserts, need to handle TypeAssertExpr
	// For calls, need to handle CallExpr in various statements
	// We'll use ast.Inspect with stack to track parent?
	// Simpler: inspect all nodes, for each CallExpr, determine context (parent statement) via stack? We can use a custom visitor that tracks parent statements.
	// Alternative: find all relevant statements (ExprStmt, AssignStmt, ValueSpec, ReturnStmt, DeferStmt, GoStmt, IfStmt, SwitchStmt, etc.) and check their contained calls/asserts?
	// Easier: for each statement type that can contain unchecked errors, check directly.
	// Let's collect all CallExpr and TypeAssertExpr with their parent statement info via traversal with parent stack.

	// We'll do a traversal that records parent chain.
	type parentInfo struct {
		node ast.Node
	}
	var stack []ast.Node
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			return true
		}
		// Check current node for being a call or assert that needs reporting, using stack for context?
		// Push
		stack = append(stack, n)
		// Handle CallExpr
		if call, ok := n.(*ast.CallExpr); ok {
			// Determine if this call's error is ignored (i.e., in ExprStmt, Defer, Go, or blank assignment, etc.)
			// Need to look at parent (stack[len-2] if exists) to determine context.
			// For now, handle in a separate pass after collecting? Let's handle here with parent.
			var parent ast.Node
			if len(stack) >= 2 {
				parent = stack[len(stack)-2]
			}
			handleCall(call, parent, stack, fset, info, src, getSrc, getFilename, excludes, ignorePkgsSet, &reports)
		}
		if ta, ok := n.(*ast.TypeAssertExpr); ok {
			var parent ast.Node
			if len(stack) >= 2 {
				parent = stack[len(stack)-2]
			}
			handleAssert(ta, parent, stack, fset, info, src, getSrc, getFilename, &reports)
		}
		return true
	})
	return reports
}

func handleCall(call *ast.CallExpr, parent ast.Node, stack []ast.Node, fset *token.FileSet, info *types.Info, src []byte, getSrc func(ast.Node) string, getFilename func(string) string, excludes []exclEntry, ignorePkgsSet map[string]bool, reports *[]report) {
	// Get function type to check if returns error
	tv, ok := info.Types[call]
	if !ok {
		return
	}
	// tv.Type is return type (single) or tuple? For call with single return, Type is that return type. For multiple, Type is tuple? Actually for CallExpr, Types[call].Type is the result type (if single) or tuple (if multiple)? Let's check: for f() (int,error), Types[call].Type is tuple (int,error)? Or is it the tuple? Yes.
	// Need to get signature of Fun to know error positions? Better to get Fun's type (signature) via info.Types[call.Fun]? Actually call.Fun's type is signature. Let's get that.
	funTv, ok := info.Types[call.Fun]
	if !ok {
		// Fun could be ident for func value? Still has type (signature)? For f() where f is var of func type, funTv.Type is signature. Good. For generic? Hmm.
		// If not found, try info.Uses/Defs? For now, return.
		return
	}
	sig, ok := funTv.Type.(*types.Signature)
	if !ok {
		return
	}
	// Check if signature has error results
	results := sig.Results()
	if results == nil {
		return
	}
	hasErr := false
	for i := 0; i < results.Len(); i++ {
		if isErrType(results.At(i).Type()) {
			hasErr = true
			break
		}
	}
	if !hasErr {
		return
	}
	// Now determine context: parent type
	// Cases:
	// - ExprStmt (call as statement): report (unless excluded/ignored)
	// - DeferStmt (Defer field == call): report
	// - GoStmt (Call == call): report
	// - AssignStmt (Rhs contains call): if blank handling? Need to handle assignments where call is on RHS.
	// - ValueSpec (Values contains call): similar to AssignStmt (var decl)
	// - Other contexts (ReturnStmt, IfStmt cond, Call args, etc.): NOT reported (since error is used, not ignored). For asserts, different (always reported if single). For calls, only Expr/Defer/Go and blank assignments are reported. Good.
	// So check parent:
	switch p := parent.(type) {
	case *ast.ExprStmt:
		// p.X == call, report
		if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
			return
		}
		// position is Lparen? Use fset.Position(call.Lparen). Actually call.Lparen is token.Pos of "(".
		pos := fset.Position(call.Lparen)
		filename := getFilename(pos.Filename)
		stmt := getSrc(p)
		var funcName string
		if *flagVerbose {
			funcName = getVerboseFunc(call, info)
		}
		*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
	case *ast.DeferStmt:
		if p.Call != call {
			return
		}
		if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
			return
		}
		pos := fset.Position(call.Lparen)
		filename := getFilename(pos.Filename)
		stmt := getSrc(p)
		var funcName string
		if *flagVerbose {
			funcName = getVerboseFunc(call, info)
		}
		*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
	case *ast.GoStmt:
		if p.Call != call {
			return
		}
		if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
			return
		}
		pos := fset.Position(call.Lparen)
		filename := getFilename(pos.Filename)
		stmt := getSrc(p)
		var funcName string
		if *flagVerbose {
			funcName = getVerboseFunc(call, info)
		}
		*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
	case *ast.AssignStmt:
		// Find which RHS index corresponds to this call? Rhs may have multiple exprs, each could be call. Our call is one of them. Need to find index.
		// For "x, y = f(), g()" etc., each call separate. For our call, find its index in Rhs.
		// Also need to handle "x = f()" where f returns (int,error) but LHS has 1 var? That's invalid (mismatch) would be load error, not here. Good. So assume valid: len(Lhs) == len(Rhs) OR len(Rhs)==1 with multi-return? Actually for "x, y := f()" where f returns 2 values, Rhs has 1 element (call) but Lhs has 2. That's the multi-return case. For "x, y = f(), g()" where each returns 1, Rhs has 2, Lhs has 2. Good.
		// We need to handle both.
		// If len(Rhs)==1 and len(Lhs)>1 and Rhs[0]==call (our call), then it's multi-return: need to map each LHS to each result.
		// Else, each Rhs[i]==call corresponds to Lhs[i] (single).
		// For blank checking (only if *flagBlank), check each error result's LHS blank.
		if !*flagBlank {
			return
		}
		// Find call index
		idx := -1
		for i, e := range p.Rhs {
			if e == call {
				idx = i
				break
			}
		}
		if idx == -1 {
			return
		}
		if len(p.Rhs) == 1 && len(p.Lhs) > 1 {
			// multi-return: call returns tuple, Lhs correspond to results
			// results.Len() should == len(Lhs) (else load error, ignore)
			if results.Len() != len(p.Lhs) {
				return
			}
			for i := 0; i < results.Len(); i++ {
				if !isErrType(results.At(i).Type()) {
					continue
				}
				lhs := p.Lhs[i]
				ident, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				if ident.Name != "_" {
					continue
				}
				// blank error found, report
				if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
					// Note: for blank assignments, does exclude/ignore still apply? Yes (as we tested, exclude os.Chdir still excludes blank assignments). Good.
					continue
				}
				// position is blank ident pos
				pos := fset.Position(ident.Pos())
				filename := getFilename(pos.Filename)
				stmt := getSrc(p)
				var funcName string
				if *flagVerbose {
					funcName = getVerboseFunc(call, info)
				}
				*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
			}
		} else {
			// single: Lhs[idx] corresponds to Rhs[idx] (which is call with single return? Or call with single but Lhs single)
			// Actually if len(Rhs)==len(Lhs), then each corresponds. Our call at idx corresponds to Lhs[idx].
			// But what if call returns multiple but Lhs single? That's invalid (load error). Ignore.
			// Check if call's single return is error and Lhs[idx] is blank.
			// For "x = f()" where f returns (int,error)? That's invalid (mismatch), ignore.
			// So assume call returns single value (results.Len()==1) and Lhs[idx] is blank.
			if results.Len() != 1 {
				// If call returns multiple but used as single? Invalid, ignore.
				return
			}
			if !isErrType(results.At(0).Type()) {
				return
			}
			if idx >= len(p.Lhs) {
				return
			}
			lhs := p.Lhs[idx]
			ident, ok := lhs.(*ast.Ident)
			if !ok {
				return
			}
			if ident.Name != "_" {
				return
			}
			if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
				return
			}
			pos := fset.Position(ident.Pos())
			filename := getFilename(pos.Filename)
			stmt := getSrc(p)
			var funcName string
			if *flagVerbose {
				funcName = getVerboseFunc(call, info)
			}
			*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
		}
	case *ast.ValueSpec:
		// var x = foo(), var _ = foo(), var ( _ = foo() )
		// Similar to AssignStmt but with Names and Values.
		if !*flagBlank {
			return
		}
		idx := -1
		for i, e := range p.Values {
			if e == call {
				idx = i
				break
			}
		}
		if idx == -1 {
			return
		}
		if len(p.Values) == 1 && len(p.Names) > 1 {
			if results.Len() != len(p.Names) {
				return
			}
			for i := 0; i < results.Len(); i++ {
				if !isErrType(results.At(i).Type()) {
					continue
				}
				ident := p.Names[i]
				if ident.Name != "_" {
					continue
				}
				if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
					continue
				}
				pos := fset.Position(ident.Pos())
				filename := getFilename(pos.Filename)
				// For ValueSpec, stmt is parent GenDecl? Actually ValueSpec is inside GenDecl (var ...). getSrc(p) would give "_ = foo()" without "var "? But observed output for "var _ = foo()" is "var _ = foo()" with "var ". Good. So need to get GenDecl, not ValueSpec. How to get GenDecl? It's grandparent (stack len-3)? Our parent is ValueSpec, grandparent is GenDecl. We need to handle.
				// Find GenDecl in stack (search upwards for *ast.GenDecl)
				var decl ast.Node
				for j := len(stack) - 1; j >= 0; j-- {
					if gd, ok := stack[j].(*ast.GenDecl); ok {
						decl = gd
						break
					}
				}
				stmtNode := ast.Node(p)
				if decl != nil {
					stmtNode = decl
				}
				stmt := getSrc(stmtNode)
				var funcName string
				if *flagVerbose {
					funcName = getVerboseFunc(call, info)
				}
				*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
			}
		} else {
			if results.Len() != 1 {
				return
			}
			if !isErrType(results.At(0).Type()) {
				return
			}
			if idx >= len(p.Names) {
				return
			}
			ident := p.Names[idx]
			if ident.Name != "_" {
				return
			}
			if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
				return
			}
			pos := fset.Position(ident.Pos())
			filename := getFilename(pos.Filename)
			var decl ast.Node
			for j := len(stack) - 1; j >= 0; j-- {
				if gd, ok := stack[j].(*ast.GenDecl); ok {
					decl = gd
					break
				}
			}
			stmtNode := ast.Node(p)
			if decl != nil {
				stmtNode = decl
			}
			stmt := getSrc(stmtNode)
			var funcName string
			if *flagVerbose {
				funcName = getVerboseFunc(call, info)
			}
			*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
		}
	default:
		// Other contexts (Return, If cond, Call args, etc.): NOT reported for calls (since error is used)
		return
	}
}

func handleAssert(ta *ast.TypeAssertExpr, parent ast.Node, stack []ast.Node, fset *token.FileSet, info *types.Info, src []byte, getSrc func(ast.Node) string, getFilename func(string) string, reports *[]report) {
	if !*flagAsserts {
		return
	}
	// Determine if single (without ok) or double (with ok) via types.Info.Types[ta].Type
	tv, ok := info.Types[ta]
	if !ok {
		return
	}
	// If Type is tuple (2 values), then it's double (comma-ok). Else single.
	if tup, ok := tv.Type.(*types.Tuple); ok && tup.Len() == 2 {
		// double: check if ok (second) is blank and *flagBlank set? Actually need both flags? Our earlier test showed double with blank only reported when BOTH asserts and blank set. Good. So if !*flagBlank, return (no report for double without blank). Good.
		if !*flagBlank {
			return
		}
