		// Parent should be AssignStmt or ValueSpec with 2 LHS and 1 RHS (the assert) where assert is in two-value context.
		// Actually double assert as "v, ok := x.(T)" has Rhs=[ta] (single) and Lhs=[v,ok] (2). Good. Similarly "_, _ = x.(T)" etc.
		// Need to find ok's LHS ident and check if blank.
		// Parent is AssignStmt or ValueSpec? Could also be Define? Actually "v, ok := ..." is AssignStmt with Tok=DEFINE. Good.
		// For other contexts where double assert is used as value? Like "foo(x.(T))" where x.(T) is double? No, double only when used with 2 LHS. In other contexts (single value), it's single. Good. So double only occurs in Assign/ValueSpec with 2 LHS.
		// Let's handle AssignStmt and ValueSpec similarly to blank calls, but for ok (bool, not error).
		switch p := parent.(type) {
		case *ast.AssignStmt:
			// Find ta index in Rhs? Should be single Rhs with ta.
			found := false
			for _, e := range p.Rhs {
				if e == ta {
					found = true
					break
				}
			}
			if !found {
				return
			}
			if len(p.Lhs) != 2 {
				return
			}
			// ok is second LHS (index 1)
			ident, ok := p.Lhs[1].(*ast.Ident)
			if !ok || ident.Name != "_" {
				return
			}
			// Report (no exclude/ignore for asserts? Asserts are not excluded via exclude file? Our earlier test showed exclude os.Chdir didn't affect asserts. Good. So no exclude check for asserts? Or should we check? For asserts, exclude file shouldn't affect (since asserts are not funcs). Good. No ignore either? Probably not. So just report.
			pos := fset.Position(ident.Pos())
			filename := getFilename(pos.Filename)
			stmt := getSrc(p)
			*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, "", stmt})
		case *ast.ValueSpec:
			found := false
			for _, e := range p.Values {
				if e == ta {
					found = true
					break
				}
			}
			if !found {
				return
			}
			if len(p.Names) != 2 {
				return
			}
			ident := p.Names[1]
			if ident.Name != "_" {
				return
			}
			pos := fset.Position(ident.Pos())
			filename := getFilename(pos.Filename)
			var decl ast.Node
			for j := len(stack) - 1; j >= 0; j-- {
				if gd, ok := stack[j].(*ast.GenDecl); ok {
					decl = gd
					break
				}
			}
			stmtNode := ast.Node(p)
			if decl != nil {
				stmtNode = decl
			}
			stmt := getSrc(stmtNode)
			*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, "", stmt})
		default:
			return
		}
		return
	}
	// single: report enclosing statement (with special handling for If/Switch?)
	// Find enclosing statement: walk stack upwards to find nearest AssignStmt, ValueSpec, ExprStmt, ReturnStmt, IfStmt, SwitchStmt, etc. that contains ta?
	// Actually parent may already be the relevant (e.g., AssignStmt for "v := x.(T)", ValueSpec for "var v = x.(T)", ExprStmt for "foo(x.(T))"? No, for "foo(x.(T))", parent of ta is CallExpr (foo(...)), grandparent is ExprStmt. Our parent here is CallExpr, not statement. How to handle? Our current parent is immediate parent (CallExpr), not statement. We need to find enclosing statement by walking stack upwards to nearest statement.
	// Let's find nearest statement in stack (from top down, excluding ta itself? Actually stack includes ta and parents. Find first parent that is a statement (AssignStmt, ExprStmt, ReturnStmt, IfStmt, etc.))
	var stmtNode ast.Node
	var stmtPos token.Pos
	// Search stack from top (ta is top? Actually stack includes ta as last? Our stack includes n (ta) as last pushed. Parent is second last. To find enclosing statement, iterate from top down (starting at parent) to find statement.
	for i := len(stack) - 1; i >= 0; i-- {
		switch n := stack[i].(type) {
		case *ast.AssignStmt, *ast.ValueSpec, *ast.ExprStmt, *ast.ReturnStmt, *ast.IfStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.ForStmt, *ast.RangeStmt, *ast.DeferStmt, *ast.GoStmt:
			_ = n
			stmtNode = stack[i]
			// For ValueSpec, need GenDecl as before? Handle later.
			// For If/Switch, need header only (up to "{")? Our getSrc for IfStmt would give full (including body) if we slice Pos to End (which is "}"). But observed output for If is only header ("if ... {"), not full. How to get header? We need to slice from Pos to Body.Pos()+1 (up to "{")? Let's do that for If/Switch.
			// For others, slice full.
			break
		}
		if stmtNode != nil {
			break
		}
	}
	if stmtNode == nil {
		// Fallback: use ta itself? Unlikely. Use parent?
		return
	}
	// Handle ValueSpec -> GenDecl
	if vs, ok := stmtNode.(*ast.ValueSpec); ok {
		for j := len(stack) - 1; j >= 0; j-- {
			if gd, ok := stack[j].(*ast.GenDecl); ok {
				stmtNode = gd
				break
			}
		}
		_ = vs
	}
	// For IfStmt, SwitchStmt, etc., need header only, not full body. How to get header? Use Body.Pos()?
	// Let's handle IfStmt and SwitchStmt specially: stmt = src[Pos:Body.Pos()+1] (up to "{")? Body.Pos() is "{" position. Good. Similarly for TypeSwitch?
	// For ForStmt, RangeStmt? Asserts in For init? Unlikely, but handle similarly? For For, header is more complex. Simpler: for If/Switch, slice to Body.
	var stmt string
	switch s := stmtNode.(type) {
	case *ast.IfStmt:
		// slice from s.Pos() to s.Body.Pos()+1 (including "{")
		start := fset.Position(s.Pos())
		bodyPos := fset.Position(s.Body.Pos())
		// Use offsets
		if start.Offset >= 0 && bodyPos.Offset >= 0 {
			// Body.Pos() is "{", need +1 to include "{"? Actually src[off:off+1] where off is Body.Pos() offset gives "{". Good. So end = bodyPos.Offset+1
			if start.Offset <= bodyPos.Offset+1 && bodyPos.Offset+1 <= len(src) {
				stmt = string(src[start.Offset : bodyPos.Offset+1])
			} else {
				stmt = getSrc(s)
			}
		} else {
			stmt = getSrc(s)
		}
	case *ast.SwitchStmt:
		start := fset.Position(s.Pos())
		bodyPos := fset.Position(s.Body.Pos())
		if start.Offset >= 0 && bodyPos.Offset >= 0 && start.Offset <= bodyPos.Offset+1 && bodyPos.Offset+1 <= len(src) {
			stmt = string(src[start.Offset : bodyPos.Offset+1])
		} else {
			stmt = getSrc(s)
		}
	case *ast.TypeSwitchStmt:
		start := fset.Position(s.Pos())
		bodyPos := fset.Position(s.Body.Pos())
		if start.Offset >= 0 && bodyPos.Offset >= 0 && start.Offset <= bodyPos.Offset+1 && bodyPos.Offset+1 <= len(src) {
			stmt = string(src[start.Offset : bodyPos.Offset+1])
		} else {
			stmt = getSrc(s)
		}
	default:
		stmt = getSrc(stmtNode)
	}
	// Position for asserts single is ta.Pos() (which is X.Pos(), i.e., start of X)? Actually ta.Pos() is X.Pos(). Good. Use that.
	pos := fset.Position(ta.Pos())
	// But for verbose, funcName is "" (no func for asserts, as observed). Good. So no funcName.
	filename := getFilename(pos.Filename)
	_ = stmtPos
	*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, "", stmt})
}

func isErrType(t types.Type) bool {
	if t == nil {
		return false
	}
	errType := types.Universe.Lookup("error").Type()
	iface, ok := errType.Underlying().(*types.Interface)
	if !ok {
		return false
	}
	return types.Implements(t, iface)
}

func getVerboseFunc(call *ast.CallExpr, info *types.Info) string {
	// Only for SelectorExpr? As observed, only SelectorExpr gives funcName, Ident gives none.
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	// Resolve selection? Use info.Selections[sel] for methods, info.Uses[sel.Sel] for package funcs?
