			if e.suffix == "os.Stderr" {
				if firstArgIsStderr {
					return true
				}
				continue
			}
			// Type suffix: check firstArgType == suffix, BUT skip if firstArg is Stdout/Stderr literal (as observed, type matching skipped for literals)
