type listPackage struct {
	Dir             string     `json:"Dir"`
	ImportPath      string     `json:"ImportPath"`
	ForTest         string     `json:"ForTest"`
	GoFiles         []string   `json:"GoFiles"`
	CompiledGoFiles []string   `json:"CompiledGoFiles"`
	TestGoFiles     []string   `json:"TestGoFiles"`
	XTestGoFiles    []string   `json:"XTestGoFiles"`
	Error           *listError `json:"Error"`
	Deps            []string   `json:"Deps"`
	Match           []string   `json:"Match"`
}

type listError struct {
	ImportStack []string `json:"ImportStack"`
	Pos         string   `json:"Pos"`
	Err         string   `json:"Err"`
}

func loadPackages(patterns []string, tags []string, mod string) ([]*listPackage, error) {
	args := []string{"list", "-e", "-json", "-compiled", "-test", "-export"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, " "))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var stdout strings.Builder
	var stderrBuf strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderrBuf
	err := cmd.Run()
	if err != nil {
		exitCode := 1
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		}
		return nil, fmt.Errorf("err: exit status %d: stderr: %s", exitCode, stderrBuf.String())
	}
	dec := json.NewDecoder(strings.NewReader(stdout.String()))
	var pkgs []*listPackage
	for {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			break
		}
		cp := p
		pkgs = append(pkgs, &cp)
	}
	return pkgs, nil
}

type importerFunc func(path string) (*types.Package, error)

func (f importerFunc) Import(path string) (*types.Package, error) { return f(path) }

type pkgResult struct {
	pkg       *listPackage
	files     []*ast.File
	info      *types.Info
	typePkg   *types.Package
	parseErrs []string
	typeErrs  []string
	fileSrc   map[string][]byte
	fnames    []string // absolute filenames in order
}

type report struct {
	filename string // as to print (relative or absolute)
	absFile  string
	line     int
	col      int
	funcName string // for verbose ("" if none)
	stmt     string
}

func run() int {
	var userExcludes []exclEntry
	if *flagExclude != "" {
		f, err := os.Open(*flagExclude)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
			return 2
		}
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			line := sc.Text()
			if line == "" {
				continue
			}
			if strings.HasPrefix(line, "//") {
				continue
			}
			b, s, h := parseExcludeLine(line)
			userExcludes = append(userExcludes, exclEntry{b, s, h})
		}
		f.Close()
	}
	var allExcludes []exclEntry
	if *flagExcludeOnly {
		allExcludes = userExcludes
	} else {
		for _, b := range builtinExcludes() {
			bb, ss, hh := parseExcludeLine(b)
			allExcludes = append(allExcludes, exclEntry{bb, ss, hh})
		}
		allExcludes = append(allExcludes, userExcludes...)
	}
	ignorePkgsSet := map[string]bool{}
	if *flagIgnorePkgStr != "" {
		for _, p := range strings.Split(*flagIgnorePkgStr, ",") {
			ignorePkgsSet[p] = true
		}
	}
	patterns := flag.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}
	pkgs, err := loadPackages(patterns, []string(*flagTags), *flagMod)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		return 2
	}
	// verbose checking order
	toPrint := pkgs
	if len(pkgs) > 0 {
		allSame := true
		d0 := pkgs[0].Dir
		for _, p := range pkgs[1:] {
			if p.Dir != d0 {
				allSame = false
				break
			}
		}
		if allSame {
			tmp := make([]*listPackage, len(pkgs))
			copy(tmp, pkgs)
			sort.Slice(tmp, func(i, j int) bool { return tmp[i].ImportPath < tmp[j].ImportPath })
			toPrint = tmp
		}
	}
	if *flagVerbose {
		for _, p := range toPrint {
			path := p.ImportPath
			if idx := strings.Index(path, " "); idx >= 0 {
				path = path[:idx]
			}
			fmt.Fprintf(os.Stderr, "checking %s\n", path)
		}
	}
	fset := token.NewFileSet()
	// order for type checking: sort by Deps length
	checkOrder := make([]*listPackage, len(pkgs))
	copy(checkOrder, pkgs)
	sort.Slice(checkOrder, func(i, j int) bool { return len(checkOrder[i].Deps) < len(checkOrder[j].Deps) })
	results := map[string]*pkgResult{}
	// importer closure
	var imp importerFunc
	imp = func(path string) (*types.Package, error) {
		for _, r := range results {
			if r.typePkg == nil {
				continue
			}
			pp := r.pkg.ImportPath
			if idx := strings.Index(pp, " "); idx >= 0 {
				pp = pp[:idx]
			}
			if pp == path {
				return r.typePkg, nil
			}
		}
		return importer.Default().Import(path)
	}
	for _, p := range checkOrder {
		res := &pkgResult{pkg: p, fileSrc: map[string][]byte{}}
		results[p.ImportPath] = res
		var filenames []string
		for _, f := range p.CompiledGoFiles {
			abs := f
			if !filepath.IsAbs(abs) {
				abs = filepath.Join(p.Dir, f)
			}
			filenames = append(filenames, abs)
		}
		res.fnames = filenames
		var files []*ast.File
		var parseErrs []string
		for _, fn := range filenames {
			src, err := os.ReadFile(fn)
			if err != nil {
				continue
			}
			res.fileSrc[fn] = src
			f, err := parser.ParseFile(fset, fn, src, parser.ParseComments)
			if err != nil {
				for _, line := range strings.Split(err.Error(), "\n") {
					if line != "" {
						parseErrs = append(parseErrs, line)
					}
				}
				if f != nil {
					files = append(files, f)
				}
				continue
			}
			files = append(files, f)
		}
		res.files = files
		res.parseErrs = parseErrs
		if len(files) == 0 {
			continue
		}
		checkPath := p.ImportPath
		if idx := strings.Index(checkPath, " "); idx >= 0 {
			checkPath = checkPath[:idx]
		}
		conf := types.Config{
			Importer: imp,
			Error: func(e error) {
				for _, line := range strings.Split(e.Error(), "\n") {
					if line != "" {
						res.typeErrs = append(res.typeErrs, line)
					}
				}
			},
		}
		info := &types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Defs:       make(map[*ast.Ident]types.Object),
			Uses:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
			Scopes:     make(map[ast.Node]*types.Scope),
		}
		tpkg, _ := conf.Check(checkPath, fset, files, info)
		res.info = info
		res.typePkg = tpkg
	}
	// check load errors in go list order (as returned, not sorted)
	for _, p := range pkgs {
		res := results[p.ImportPath]
		var relErr string
		if p.Error != nil && p.Error.Err != "" {
			relErr = p.Error.Err
		}
		var absErrs []string
		if res != nil {
