		pos := fset.Position(call.Lparen)
		filename := getFilename(pos.Filename)
		stmt := getSrc(p)
		var funcName string
		if *flagVerbose {
			funcName = getVerboseFunc(call, info)
		}
		*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
