type ignoreEntry struct {
	pkg string
	re  *regexp.Regexp
}
type ignoreFlag []ignoreEntry

func (f *ignoreFlag) String() string { return "" }
func (f *ignoreFlag) Set(s string) error {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	for _, p := range parts {
		var pkg, reStr string
		if idx := strings.Index(p, ":"); idx >= 0 {
			pkg = p[:idx]
			reStr = p[idx+1:]
		} else {
			pkg = ""
			reStr = p
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return err
		}
		*f = append(*f, ignoreEntry{pkg: pkg, re: re})
	}
	return nil
}

type tagsFlag []string

func (f *tagsFlag) String() string { return "" }
func (f *tagsFlag) Set(s string) error {
	if s == "" {
