func checkFile(fset *token.FileSet, f *ast.File, src []byte, info *types.Info, excludes []exclEntry, ignorePkgsSet map[string]bool, cwd string) []report {
	var reports []report
	// Helper to get source slice for node
	getSrc := func(n ast.Node) string {
		start := fset.Position(n.Pos())
		end := fset.Position(n.End())
		// Use offsets? fset.Position gives Offset? Actually Position has Offset field. Use File.Offset?
		// Simpler: use start.Offset and end.Offset (byte offsets in file). Since src is file content, slice.
		// Position.Offset is byte offset. Good.
		if start.Offset < 0 || end.Offset < 0 || start.Offset > len(src) || end.Offset > len(src) || start.Offset > end.Offset {
			return ""
		}
		return string(src[start.Offset:end.Offset])
	}
	// Helper to get filename to print (relative or absolute)
	getFilename := func(abs string) string {
		if *flagAbspath {
			return abs
		}
		rel, err := filepath.Rel(cwd, abs)
		if err != nil {
			return abs
		}
		return rel
	}
	// Helper to check if call returns error (any error return)
	isErrorResult := func(sig *types.Signature) (bool, []int) {
		// returns (hasError, indices of error results)
		results := sig.Results()
		if results == nil {
			return false, nil
		}
		var idxs []int
		for i := 0; i < results.Len(); i++ {
			v := results.At(i)
			if isErrorType(v.Type()) {
				idxs = append(idxs, i)
			}
		}
		return len(idxs) > 0, idxs
	}
	isErrorType := func(t types.Type) bool {
		// check if type is error (interface with Error() string)
		// Use types.Universe.Lookup("error")? Or check Implements?
		errType := types.Universe.Lookup("error").Type()
		// t must implement error and be exactly error? Actually any type that is error interface? For our purposes, check if t == error or implements error? In Go, error return is always exactly "error" (universe), not custom? Actually functions can return custom error types that implement error? But errcheck likely checks if type is error interface (i.e., implements error)? Let's check: if func returns custom error type MyError (which implements error), does errcheck report? Likely yes (since it's error). How to check? Use types.Implements(t, errType.(*types.Interface))? And also check if t is error itself? For simplicity, check Implements.
		// But need to handle named types? Use Implements.
		if t == nil {
			return false
		}
		// If t is Tuple? No, Signature.Results() gives individual types, not tuple. Good.
		// Check if t implements error
		iface, ok := errType.Underlying().(*types.Interface)
		if !ok {
			return false
		}
		// types.Implements requires t implements iface
		// For error type itself, Implements returns true? Yes.
		return types.Implements(t, iface)
	}
	_ = isErrorResult
	_ = isErrorType
	// Walk to find calls and asserts
	// For asserts, need to handle TypeAssertExpr
	// For calls, need to handle CallExpr in various statements
	// We'll use ast.Inspect with stack to track parent?
	// Simpler: inspect all nodes, for each CallExpr, determine context (parent statement) via stack? We can use a custom visitor that tracks parent statements.
	// Alternative: find all relevant statements (ExprStmt, AssignStmt, ValueSpec, ReturnStmt, DeferStmt, GoStmt, IfStmt, SwitchStmt, etc.) and check their contained calls/asserts?
	// Easier: for each statement type that can contain unchecked errors, check directly.
	// Let's collect all CallExpr and TypeAssertExpr with their parent statement info via traversal with parent stack.

	// We'll do a traversal that records parent chain.
	type parentInfo struct {
		node ast.Node
	}
	var stack []ast.Node
	ast.Inspect(f, func(n ast.Node) bool {
		if n == nil {
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			return true
		}
		// Check current node for being a call or assert that needs reporting, using stack for context?
		// Push
		stack = append(stack, n)
		// Handle CallExpr
		if call, ok := n.(*ast.CallExpr); ok {
			// Determine if this call's error is ignored (i.e., in ExprStmt, Defer, Go, or blank assignment, etc.)
			// Need to look at parent (stack[len-2] if exists) to determine context.
			// For now, handle in a separate pass after collecting? Let's handle here with parent.
			var parent ast.Node
			if len(stack) >= 2 {
				parent = stack[len(stack)-2]
			}
			handleCall(call, parent, stack, fset, info, src, getSrc, getFilename, excludes, ignorePkgsSet, &reports)
		}
		if ta, ok := n.(*ast.TypeAssertExpr); ok {
			var parent ast.Node
			if len(stack) >= 2 {
				parent = stack[len(stack)-2]
			}
			handleAssert(ta, parent, stack, fset, info, src, getSrc, getFilename, &reports)
		}
		return true
	})
	return reports
}

func handleCall(call *ast.CallExpr, parent ast.Node, stack []ast.Node, fset *token.FileSet, info *types.Info, src []byte, getSrc func(ast.Node) string, getFilename func(string) string, excludes []exclEntry, ignorePkgsSet map[string]bool, reports *[]report) {
