		stmt := getSrc(p)
		var funcName string
		if *flagVerbose {
			funcName = getVerboseFunc(call, info)
		}
		*reports = append(*reports, report{filename, pos.Filename, pos.Line, pos.Column, funcName, stmt})
	case *ast.GoStmt:
		if p.Call != call {
			return
		}
		if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
			return
		}
