				return
			}
			for i := 0; i < results.Len(); i++ {
				if !isErrType(results.At(i).Type()) {
					continue
				}
				ident := p.Names[i]
				if ident.Name != "_" {
					continue
				}
				if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
