			}
			ident := p.Names[idx]
			if ident.Name != "_" {
				return
			}
			if isExcludedCall(call, info, excludes) || isIgnoredCall(call, info) {
				return
			}
			pos := fset.Position(ident.Pos())
			filename := getFilename(pos.Filename)
			var decl ast.Node
			for j := len(stack) - 1; j >= 0; j-- {
