			if obj, ok := info.Uses[sel.Sel]; ok {
				if v, ok := obj.(*types.Var); ok {
					if v.Pkg() != nil && v.Pkg().Path() == "os" && (v.Name() == "Stdout" || v.Name() == "Stderr") {
						// Check that X is package os (not value)? For "os.Stdout", X is Ident "os" which is package name (PkgName). Uses[X]? Actually X is package, not value. But we can still consider it literal if Sel is Stdout/Stderr and Pkg is os.
						// Need to ensure X is package os (not shadowed)? For alias "o.Stdout" where o is alias for os, X is "o" (package name alias), Sel is "Stdout", Uses[Sel] still resolves to os.Stdout var (since alias). Good. So we consider it literal regardless of X name, as long as Var is os.Stdout/Stderr.
						// But for dot import "Stdout" (Ident, not Selector), not here. Good.
						// For "w" variable holding Stdout (not Selector), not here. Good.
						if v.Name() == "Stdout" {
							firstArgIsStdout = true
						} else {
							firstArgIsStderr = true
						}
					}
				}
			}
			// Also need to handle Selections? For "os.Stdout" where os is package, Selections[sel] is nil (since X is package, not value). Good. So Uses check is correct.
		}
		// Get type string for first arg (for suffix matching, unless it's Stdout/Stderr literal? Actually for Stdout/Stderr literals, type matching should be skipped (as observed, *os.File didn't match Stdout). Good. So if literal, don't set firstArgType? Or set but skip type matching later? We'll handle in matching: if literal, only check literal suffixes, not type suffixes.
		if tv, ok := info.Types[arg]; ok && tv.Type != nil {
