			obj := selection.Obj()
			if fn, ok := obj.(*types.Func); ok {
				sig, _ := fn.Type().(*types.Signature)
				if sig != nil && sig.Recv() != nil {
					objRecv := sig.Recv().Type().String()
					objBase := "(" + objRecv + ")." + fn.Name()
					bases = append(bases, objBase)
				}
			}
			// Recv base
			recvType := selection.Recv()
			if recvType != nil {
				recvStr := recvType.String()
				// Need method name? Obj().Name()? Use selection.Obj().Name()?
				if fn, ok := selection.Obj().(*types.Func); ok {
					recvBase := "(" + recvStr + ")." + fn.Name()
					bases = append(bases, recvBase)
				}
			}
		} else {
			// Package func (X is package)
			if obj, ok := info.Uses[sel.Sel]; ok {
				if fn, ok := obj.(*types.Func); ok {
					if pkg := fn.Pkg(); pkg != nil {
						base := pkg.Path() + "." + fn.Name()
