		if obj, ok := info.Uses[ident]; ok {
			if fn, ok := obj.(*types.Func); ok {
				if pkg := fn.Pkg(); pkg != nil {
					base := pkg.Path() + "." + fn.Name()
					bases = append(bases, base)
				} else {
					// builtin? Unlikely. Skip.
				}
			}
		} else if obj, ok := info.Defs[ident]; ok {
			// For "v := foo()" where foo is defined? Actually Uses vs Defs? For call Fun ident, it's Uses (since used). Good. Defs for definitions. Skip.
			_ = obj
		}
	} else {
		// Other Fun types (e.g., FuncLit, ParenExpr, etc.)? For "func() error {...}()" (immediately invoked) or "(f)()" etc. Those are not direct func references, so no base, not excluded. Good. Return false.
		return false
	}
	if len(bases) == 0 {
		return false
	}
	// Check each exclude entry
	for _, e := range excludes {
		for _, b := range bases {
			if b != e.base {
				continue
			}
			if !e.hasSuffix {
				return true
			}
			// Has suffix: need to match first arg
			if e.suffix == "os.Stdout" {
				if firstArgIsStdout {
					return true
				}
				continue
			}
			if e.suffix == "os.Stderr" {
				if firstArgIsStderr {
					return true
				}
				continue
			}
			// Type suffix: check firstArgType == suffix, BUT skip if firstArg is Stdout/Stderr literal (as observed, type matching skipped for literals)
			if firstArgIsStdout || firstArgIsStderr {
				continue
			}
			if firstArgType == e.suffix {
				return true
			}
			// Note: for methods, first arg is first param after receiver? Our firstArgType is for call.Args[0] (first param). Good. For "f.Write([]byte(...))", first arg type is "[]byte", suffix would be "[]byte". Good. Our earlier test showed "(*os.File).Write([]byte)" matched, "([]uint8)" didn't (since type string is "[]byte", not "[]uint8"). Good.
		}
	}
	return false
}

